PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE d1_migrations(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE users (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  email TEXT UNIQUE NOT NULL,
  password_hash TEXT NOT NULL,
  name TEXT NOT NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE companies (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL,
  ticker TEXT NOT NULL,
  company_name TEXT NOT NULL,
  market_cap REAL,
  exchange TEXT,
  next_earnings_date DATE,
  sector TEXT,
  industry TEXT,
  is_wonderful INTEGER DEFAULT 0, 
  research_score INTEGER,
  anti_fragile_score INTEGER,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, buy_price REAL, data_refreshed_at DATETIME, data_refresh_error TEXT, earnings_estimated INTEGER DEFAULT 0, pe_eps_ttm REAL, pe_current REAL, pe_min REAL, pe_p5 REAL, pe_median REAL, pe_p95 REAL, pe_max REAL, pe_percentile INTEGER, pe_months INTEGER, pe_updated_at DATETIME, pe_error TEXT,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE account_balances (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL,
  account_type TEXT NOT NULL, 
  balance_cad REAL DEFAULT 0,
  balance_usd REAL DEFAULT 0,
  cash_balance_usd REAL DEFAULT 0,
  month INTEGER NOT NULL,
  year INTEGER NOT NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, account_name VARCHAR(100),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  UNIQUE(user_id, account_type, month, year)
);
CREATE TABLE stock_trades (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL,
  company_id INTEGER,
  ticker TEXT NOT NULL,
  trade_type TEXT NOT NULL, 
  quantity INTEGER NOT NULL,
  price REAL NOT NULL,
  account_type TEXT NOT NULL,
  trade_date DATE NOT NULL,
  is_open INTEGER DEFAULT 1, 
  cost_basis_adjustment REAL DEFAULT 0, 
  notes TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, account_id INTEGER, commission DECIMAL(10, 2) DEFAULT 0, close_date DATE, close_price DECIMAL(10, 2), close_commission DECIMAL(10, 2) DEFAULT 0, profit_loss DECIMAL(10, 2),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (company_id) REFERENCES companies(id) ON DELETE SET NULL
);
CREATE TABLE option_trades (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL,
  company_id INTEGER,
  ticker TEXT NOT NULL,
  strategy_type TEXT NOT NULL, 
  strike_price REAL NOT NULL,
  strike_price_2 REAL, 
  strike_price_3 REAL, 
  strike_price_4 REAL, 
  premium REAL NOT NULL,
  quantity INTEGER NOT NULL, 
  expiration_date DATE NOT NULL,
  account_type TEXT NOT NULL,
  trade_date DATE NOT NULL,
  is_open INTEGER DEFAULT 1, 
  close_date DATE,
  close_price REAL,
  profit_loss REAL,
  notes TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, short_strike DECIMAL(10, 2), long_strike DECIMAL(10, 2), spread_width DECIMAL(10, 2), account_id INTEGER, commission REAL DEFAULT 0, close_commission DECIMAL(10, 2) DEFAULT 0, close_price_2 REAL, close_price_3 REAL, close_price_4 REAL, premium_2 REAL, premium_3 REAL, premium_4 REAL,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (company_id) REFERENCES companies(id) ON DELETE SET NULL
);
CREATE TABLE accounts (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL,
  account_name VARCHAR(100) NOT NULL,
  account_type TEXT NOT NULL,
  balance_cad DECIMAL(15, 2) DEFAULT 0,
  balance_usd DECIMAL(15, 2) DEFAULT 0,
  cash_balance_usd DECIMAL(15, 2) DEFAULT 0,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, default_currency TEXT DEFAULT 'CAD', cash_balance_cad REAL DEFAULT 0,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE account_balance_history (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL,
  account_id INTEGER NOT NULL,
  balance REAL NOT NULL,
  cash_balance REAL NOT NULL,
  currency TEXT NOT NULL,
  month INTEGER NOT NULL,
  year INTEGER NOT NULL,
  exchange_rate_to_usd REAL DEFAULT 1.0,
  exchange_rate_to_cad REAL DEFAULT 1.0,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (user_id) REFERENCES users(id),
  FOREIGN KEY (account_id) REFERENCES accounts(id) ON DELETE CASCADE,
  UNIQUE(account_id, month, year)
);
CREATE TABLE exchange_rates (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  month INTEGER NOT NULL,
  year INTEGER NOT NULL,
  usd_to_cad REAL NOT NULL,
  cad_to_usd REAL NOT NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(month, year)
);
CREATE TABLE daily_trade_config (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    
    
    max_contract_limit INTEGER NOT NULL DEFAULT 25,
    rolling_profit_window INTEGER NOT NULL DEFAULT 50,
    
    
    target_premium_min DECIMAL(10,2) NOT NULL DEFAULT 10.00,
    target_premium_max DECIMAL(10,2) NOT NULL DEFAULT 15.00,
    strike_width INTEGER NOT NULL DEFAULT 5,
    default_contracts INTEGER NOT NULL DEFAULT 1,
    
    
    profit_target_percent INTEGER NOT NULL DEFAULT 50,
    atm_proximity_limit INTEGER NOT NULL DEFAULT 30,
    time_exit TIME NOT NULL DEFAULT '14:00:00',
    
    
    default_account_id INTEGER,
    
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, guideline_delta DECIMAL(10,4) DEFAULT -0.10, enable_profit_sizing_default INTEGER DEFAULT 0, enable_position_sizing INTEGER DEFAULT 0, position_sizing_type TEXT DEFAULT 'profit', account_max_loss_percent DECIMAL(5,2) DEFAULT 4.00,
    
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (default_account_id) REFERENCES accounts(id) ON DELETE SET NULL,
    UNIQUE(user_id)
);
CREATE TABLE daily_trades (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    account_id INTEGER,
    
    
    trade_date DATE NOT NULL,
    entry_time TIME NOT NULL,
    exit_time TIME,
    
    
    strategy_type TEXT NOT NULL CHECK(strategy_type IN ('IRON_CONDOR', 'CREDIT_SPREAD_CALL', 'CREDIT_SPREAD_PUT')),
    contracts INTEGER NOT NULL,
    
    
    call_enabled INTEGER DEFAULT 0,
    call_short_strike DECIMAL(10,2),
    call_total_credit DECIMAL(10,2),
    call_close_debit DECIMAL(10,2),
    
    
    put_enabled INTEGER DEFAULT 0,
    put_short_strike DECIMAL(10,2),
    put_total_credit DECIMAL(10,2),
    put_close_debit DECIMAL(10,2),
    
    
    spx_entry_price DECIMAL(10,2),
    spx_exit_price DECIMAL(10,2),
    
    
    total_credit DECIMAL(10,2) NOT NULL,
    total_debit DECIMAL(10,2),
    commission DECIMAL(10,2) DEFAULT 0,
    profit_loss DECIMAL(10,2),
    
    
    exit_reason TEXT CHECK(exit_reason IN ('PROFIT_TARGET', 'ATM_PROXIMITY', 'TIME_EXIT', 'MANUAL', 'STOP_LOSS')),
    
    
    is_open INTEGER DEFAULT 1,
    
    
    notes TEXT,
    
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, close_commission DECIMAL(10,2) DEFAULT 0, vix_entry_price DECIMAL(10,2), strike_width INTEGER DEFAULT 5,
    
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (account_id) REFERENCES accounts(id) ON DELETE SET NULL
);
CREATE TABLE stock_transactions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL,
  holding_id INTEGER NOT NULL,
  transaction_type TEXT NOT NULL CHECK(transaction_type IN ('BUY', 'SELL')),
  shares INTEGER NOT NULL,
  price_per_share REAL NOT NULL,
  transaction_date DATE NOT NULL,
  commission REAL DEFAULT 0,
  notes TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP, option_trade_id INTEGER,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (holding_id) REFERENCES stock_holdings(id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS "cost_basis_adjustments" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL,
  holding_id INTEGER NOT NULL,
  adjustment_type TEXT NOT NULL CHECK(adjustment_type IN ('DIVIDEND', 'COVERED_CALL', 'SELLING_PUT')),
  amount REAL NOT NULL,
  adjustment_date DATE NOT NULL,
  notes TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, option_trade_id INTEGER,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (holding_id) REFERENCES stock_holdings(id) ON DELETE CASCADE
);
CREATE TABLE dividend_repository (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  ticker TEXT NOT NULL,
  
  
  ex_date DATE NOT NULL,           
  record_date DATE,                 
  pay_date DATE,                    
  declared_date DATE,               
  amount REAL NOT NULL,             
  frequency TEXT,                   
  currency TEXT DEFAULT 'USD',      
  
  
  api_source TEXT DEFAULT 'rapidapi_dividend_tracker',
  fetch_date DATETIME DEFAULT CURRENT_TIMESTAMP,
  
  
  status TEXT DEFAULT 'active',     
  notes TEXT,
  
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, manually_edited INTEGER DEFAULT 0,
  
  UNIQUE(ticker, ex_date)  
);
CREATE TABLE api_configurations (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL,
  api_name TEXT NOT NULL,           
  api_key TEXT NOT NULL,            
  api_host TEXT,                    
  settings TEXT,                    
  is_active INTEGER DEFAULT 1,      
  last_used DATETIME,               
  rate_limit_remaining INTEGER,     
  rate_limit_reset DATETIME,        
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  UNIQUE(user_id, api_name)
);
CREATE TABLE dividend_fetch_logs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL,
  fetch_type TEXT NOT NULL,         
  status TEXT NOT NULL,              
  tickers_processed TEXT,            
  dividends_found INTEGER DEFAULT 0,
  dividends_eligible INTEGER DEFAULT 0,
  api_calls_made INTEGER DEFAULT 0,
  error_message TEXT,
  fetch_duration_ms INTEGER,        
  started_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  completed_at DATETIME,
  
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS "stock_holdings" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL,
  company_id INTEGER,
  ticker TEXT NOT NULL,
  account_id INTEGER,
  total_shares REAL NOT NULL,
  average_price REAL NOT NULL,
  is_open INTEGER DEFAULT 1,
  opened_date DATE NOT NULL,
  closed_date DATE,
  strategy_type TEXT,
  notes TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (company_id) REFERENCES companies(id) ON DELETE CASCADE,
  FOREIGN KEY (account_id) REFERENCES accounts(id) ON DELETE SET NULL
);
CREATE TABLE user_preferences (
  user_id INTEGER PRIMARY KEY,
  menu_hidden TEXT NOT NULL DEFAULT '[]',
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_companies_user_id ON companies(user_id);
CREATE INDEX idx_companies_ticker ON companies(ticker);
CREATE INDEX idx_account_balances_user_id ON account_balances(user_id);
CREATE INDEX idx_stock_trades_user_id ON stock_trades(user_id);
CREATE INDEX idx_stock_trades_ticker ON stock_trades(ticker);
CREATE INDEX idx_option_trades_user_id ON option_trades(user_id);
CREATE INDEX idx_option_trades_ticker ON option_trades(ticker);
CREATE INDEX idx_users_email ON users(email);
CREATE INDEX idx_option_trades_account_id ON option_trades(account_id);
CREATE INDEX idx_stock_trades_account_id ON stock_trades(account_id);
CREATE INDEX idx_accounts_user_id ON accounts(user_id);
CREATE INDEX idx_balance_history_account ON account_balance_history(account_id);
CREATE INDEX idx_balance_history_date ON account_balance_history(year DESC, month DESC);
CREATE INDEX idx_balance_history_user ON account_balance_history(user_id);
CREATE INDEX idx_exchange_rates_date ON exchange_rates(year DESC, month DESC);
CREATE INDEX idx_daily_trade_config_user_id ON daily_trade_config(user_id);
CREATE INDEX idx_daily_trades_user_date ON daily_trades(user_id, trade_date DESC);
CREATE INDEX idx_daily_trades_user_open ON daily_trades(user_id, is_open);
CREATE INDEX idx_daily_trades_date ON daily_trades(trade_date DESC);
CREATE INDEX idx_stock_transactions_user_id ON stock_transactions(user_id);
CREATE INDEX idx_stock_transactions_holding_id ON stock_transactions(holding_id);
CREATE INDEX idx_stock_transactions_date ON stock_transactions(transaction_date);
CREATE INDEX idx_cost_basis_adjustments_user_id ON cost_basis_adjustments(user_id);
CREATE INDEX idx_cost_basis_adjustments_holding_id ON cost_basis_adjustments(holding_id);
CREATE INDEX idx_dividend_repository_ticker ON dividend_repository(ticker);
CREATE INDEX idx_dividend_repository_ex_date ON dividend_repository(ex_date);
CREATE INDEX idx_dividend_repository_pay_date ON dividend_repository(pay_date);
CREATE INDEX idx_dividend_repository_status ON dividend_repository(status);
CREATE INDEX idx_api_configurations_user_id ON api_configurations(user_id);
CREATE INDEX idx_api_configurations_api_name ON api_configurations(api_name);
CREATE INDEX idx_dividend_fetch_logs_user_id ON dividend_fetch_logs(user_id);
CREATE INDEX idx_dividend_fetch_logs_started_at ON dividend_fetch_logs(started_at);
CREATE INDEX idx_dividend_repository_manually_edited ON dividend_repository(manually_edited);
CREATE INDEX idx_stock_holdings_user_id ON stock_holdings(user_id);
CREATE INDEX idx_stock_holdings_company_id ON stock_holdings(company_id);
CREATE INDEX idx_stock_holdings_account_id ON stock_holdings(account_id);
CREATE INDEX idx_stock_holdings_ticker ON stock_holdings(ticker);
CREATE INDEX idx_stock_holdings_is_open ON stock_holdings(is_open);
CREATE INDEX idx_stock_holdings_strategy_type ON stock_holdings(strategy_type);
CREATE INDEX idx_cost_basis_adjustments_option_trade_id ON cost_basis_adjustments(option_trade_id);
CREATE INDEX idx_stock_transactions_option_trade_id ON stock_transactions(option_trade_id);
